const guestResetGuestSession = `-- name: GuestResetGuestSession :one
UPDATE club_computers
SET current_session_id = NULL, current_session_user_id = NULL, session_guest = false, session_ends_at = NULL,
    updated_at = $1
WHERE club_id = $2 AND id = $3
  AND session_guest
  AND current_session_id IS NOT NULL
  AND session_ends_at > $1
RETURNING id, number, display_name, device_name, current_session_id
`

type GuestResetGuestSessionParams struct {
	Now    *time.Time `json:"now"`
	ClubID int64      `json:"club_id"`
	ID     int64      `json:"id"`
}

type GuestResetGuestSessionRow struct {
	ID               int64   `json:"id"`
	Number           int64   `json:"number"`
	DisplayName      *string `json:"display_name"`
	DeviceName       *string `json:"device_name"`
	CurrentSessionID *string `json:"current_session_id"`
}

// ClubComputerSessions::resetGuestSession(): гостевая сессия с кассы (session_guest, hasPaidSession()) не
// переживает перезагрузку ПК — поля сессии в NULL. Нет такой сессии — нет строки.
func (q *Queries) GuestResetGuestSession(ctx context.Context, arg GuestResetGuestSessionParams) (GuestResetGuestSessionRow, error) {
	row := q.db.QueryRow(ctx, guestResetGuestSession, arg.Now, arg.ClubID, arg.ID)
	var i GuestResetGuestSessionRow
	err := row.Scan(
		&i.ID,
		&i.Number,
		&i.DisplayName,
		&i.DeviceName,
		&i.CurrentSessionID,
	)
	return i, err
}

