const guestTariffNames = `-- name: GuestTariffNames :many
SELECT id, name
FROM tariffs
WHERE club_id = $1 AND id = ANY($2::bigint[])
`

type GuestTariffNamesParams struct {
	ClubID int64   `json:"club_id"`
	Ids    []int64 `json:"ids"`
}

type GuestTariffNamesRow struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

// Tariff::withTrashed()->whereKey($ids)->pluck('name', 'id').
func (q *Queries) GuestTariffNames(ctx context.Context, arg GuestTariffNamesParams) ([]GuestTariffNamesRow, error) {
	rows, err := q.db.Query(ctx, guestTariffNames, arg.ClubID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GuestTariffNamesRow
	for rows.Next() {
		var i GuestTariffNamesRow
		if err := rows.Scan(&i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const guestTranslationsVersion = `-- name: GuestTranslationsVersion :one

SELECT COALESCE(floor(extract(epoch FROM greatest(
           (SELECT max(GREATEST(t.updated_at, t.created_at)) FROM translations t),
           (SELECT max(GREATEST(l.updated_at, l.created_at)) FROM languages l))) * 1000), 0)::bigint AS version
WHERE EXISTS (SELECT 1 FROM club_computers c WHERE c.club_id = $1 AND c.id = $2)
`

type GuestTranslationsVersionParams struct {
	ClubID     int64 `json:"club_id"`
	ComputerID int64 `json:"computer_id"`
}

// ---------------------------------------------------------------------------
// Переводы агента (TranslationCatalog, AgentTranslationController)
// ---------------------------------------------------------------------------
// Версия переводов: в Laravel — счётчик в кэше (TranslationCatalog::flush()). Здесь — момент последнего
// изменения строк и языков в миллисекундах (правка суперадмина обновляет updated_at), 0 — строк нет.
// Ограничено ПК клуба: переводы получает только подключённый ПК.
func (q *Queries) GuestTranslationsVersion(ctx context.Context, arg GuestTranslationsVersionParams) (int64, error) {
	row := q.db.QueryRow(ctx, guestTranslationsVersion, arg.ClubID, arg.ComputerID)
	var version int64
	err := row.Scan(&version)
	return version, err
}

